package by.bsuir.workorder;
import by.bsuir.repair.contract.*; import by.bsuir.repair.runtime.*; import io.grpc.*; import io.grpc.stub.StreamObserver; import jakarta.annotation.PreDestroy; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.math.*; import java.time.*; import java.util.*; import java.util.concurrent.TimeUnit;
@Service public class WorkOrderGrpcService extends WorkOrderServiceGrpc.WorkOrderServiceImplBase {
 
 private final JdbcTemplate jdbc; private final Jsons jsons; private final OutboxService outbox; private final ManagedChannel requestChannel,catalogChannel; private final RepairRequestServiceGrpc.RepairRequestServiceBlockingStub requests; private final CatalogServiceGrpc.CatalogServiceBlockingStub catalog;
 public WorkOrderGrpcService(JdbcTemplate jdbc,Jsons jsons,OutboxService outbox,@Value("${integration.request.host:localhost}")String rh,@Value("${integration.request.port:9103}")int rp,@Value("${integration.catalog.host:localhost}")String ch,@Value("${integration.catalog.port:9105}")int cp){this.jdbc=jdbc;this.jsons=jsons;this.outbox=outbox;requestChannel=ManagedChannelBuilder.forAddress(rh,rp).usePlaintext().intercept(GrpcCorrelation.client()).build();catalogChannel=ManagedChannelBuilder.forAddress(ch,cp).usePlaintext().intercept(GrpcCorrelation.client()).build();requests=RepairRequestServiceGrpc.newBlockingStub(requestChannel);catalog=CatalogServiceGrpc.newBlockingStub(catalogChannel);}
 @PreDestroy void close(){requestChannel.shutdown();catalogChannel.shutdown();}
 @Override public void getWorkOrder(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);var value=full(UUID.fromString(jsons.string(in,"id")));authorize(value,in);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void listWorkOrders(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);String sql="select id from work_orders";List<Object> args=new ArrayList<>();if("CLIENT".equals(Objects.toString(in.get("role")))){sql+=" where client_id=?";args.add(UUID.fromString(jsons.string(in,"currentUserId")));}String field="TOTAL_AMOUNT".equals(Objects.toString(in.get("sortField")))?"total_amount":"created_at";sql+=" order by "+field+("ASC".equals(Objects.toString(in.get("sortDirection")))?" asc":" desc");var ids=jdbc.queryForList(sql,UUID.class,args.toArray());var values=ids.stream().map(this::full).toList();jsons.reply(obs,Map.of("items",values,"totalElements",values.size()));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void diagnoseAndCreate(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireStaff(in);UUID requestId=UUID.fromString(jsons.string(in,"requestId"));if(jdbc.queryForObject("select count(*) from work_orders where repair_request_id=?",Integer.class,requestId)>0)throw Status.ALREADY_EXISTS.withDescription("Work order already exists").asRuntimeException();var snapshot=rpcRead(requests.withDeadlineAfter(1500,TimeUnit.MILLISECONDS).getRequestSnapshot(jsons.write(Map.of("id",requestId))));String status=snapshot.get("status").toString();if(!Set.of("DIAGNOSING","IN_PROGRESS").contains(status))throw Status.FAILED_PRECONDITION.withDescription("Request must be in diagnostics").asRuntimeException();UUID id=UUID.randomUUID(),employee=UUID.fromString(jsons.string(in,"currentUserId")),client=UUID.fromString(snapshot.get("clientId").toString());var now=java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC);jdbc.update("insert into work_orders(id,repair_request_id,client_id,employee_id,diagnosis,status,total_amount,created_at,updated_at) values(?,?,?,?,?,?,?,?,?)",id,requestId,client,employee,jsons.string(in,"diagnosis"),"DIAGNOSED",BigDecimal.ZERO,now,now);history(id,null,"DIAGNOSED",employee);var value=full(id);outbox.enqueue(EventTopics.WORK_ORDER,"WorkOrderCreated",id,value);jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void addService(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireStaff(in);UUID orderId=UUID.fromString(jsons.string(in,"workOrderId")),serviceId=UUID.fromString(jsons.string(in,"serviceId"));int qty=Math.max(1,jsons.integer(in,"quantity",1));ensureEditable(orderId);var services=rpcList(catalog.withDeadlineAfter(1500,TimeUnit.MILLISECONDS).listServices(jsons.write(Map.of("activeOnly",true))));var item=services.stream().filter(x->x.get("id").toString().equals(serviceId.toString())).findFirst().orElseThrow(()->Status.NOT_FOUND.withDescription("Service not found").asRuntimeException());BigDecimal price=new BigDecimal(item.get("price").toString());jdbc.update("insert into work_order_services(id,work_order_id,service_id,service_name,unit_price,quantity,line_total) values(?,?,?,?,?,?,?)",UUID.randomUUID(),orderId,serviceId,item.get("name"),price,qty,price.multiply(BigDecimal.valueOf(qty)));var value=recalculateInternal(orderId);outbox.enqueue(EventTopics.WORK_ORDER,"WorkOrderServiceAdded",orderId,Map.of("workOrderId",orderId,"serviceId",serviceId,"serviceName",item.get("name"),"quantity",qty,"revenue",price.multiply(BigDecimal.valueOf(qty))));jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void addPart(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireStaff(in);UUID orderId=UUID.fromString(jsons.string(in,"workOrderId")),partId=UUID.fromString(jsons.string(in,"partId"));int qty=Math.max(1,jsons.integer(in,"quantity",1));ensureEditable(orderId);String key=Objects.toString(in.getOrDefault("idempotencyKey",UUID.randomUUID().toString()));var response=rpcRead(catalog.withDeadlineAfter(1500,TimeUnit.MILLISECONDS).reserveParts(jsons.write(Map.of("workOrderId",orderId,"idempotencyKey",key,"items",List.of(Map.of("partId",partId,"quantity",qty))))));@SuppressWarnings("unchecked")var items=(List<Map<String,Object>>)response.get("items");var item=items.get(0);BigDecimal price=new BigDecimal(item.get("price").toString());jdbc.update("insert into work_order_parts(id,work_order_id,part_id,part_name,unit_price,quantity,line_total,reservation_key) values(?,?,?,?,?,?,?,?)",UUID.randomUUID(),orderId,partId,item.get("name"),price,qty,price.multiply(BigDecimal.valueOf(qty)),key);jsons.reply(obs,recalculateInternal(orderId));}catch(Throwable e){jsons.fail(obs,e);}}
 @Override @Transactional public void recalculate(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireStaff(in);jsons.reply(obs,recalculateInternal(UUID.fromString(jsons.string(in,"workOrderId"))));}catch(Throwable e){jsons.fail(obs,e);}}
 private Map<String,Object> recalculateInternal(UUID id){BigDecimal services=Optional.ofNullable(jdbc.queryForObject("select coalesce(sum(line_total),0) from work_order_services where work_order_id=?",BigDecimal.class,id)).orElse(BigDecimal.ZERO);BigDecimal parts=Optional.ofNullable(jdbc.queryForObject("select coalesce(sum(line_total),0) from work_order_parts where work_order_id=?",BigDecimal.class,id)).orElse(BigDecimal.ZERO);jdbc.update("update work_orders set total_amount=?,updated_at=? where id=?",services.add(parts),java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);var value=full(id);outbox.enqueue(EventTopics.WORK_ORDER,"WorkOrderCostCalculated",id,Map.of("workOrderId",id,"repairRequestId",value.get("repairRequestId"),"totalAmount",services.add(parts)));return value;}
 @Override @Transactional public void changeStatus(JsonMessage req,StreamObserver<JsonMessage> obs){try{var in=jsons.read(req);requireStaff(in);UUID id=UUID.fromString(jsons.string(in,"workOrderId"));var current=full(id);String from=current.get("status").toString(),to=jsons.string(in,"status");if(!DomainRules.workOrderTransition(from,to))throw new IllegalArgumentException("Status transition from "+from+" to "+to+" is not allowed");jdbc.update("update work_orders set status=?,updated_at=? where id=?",to,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC),id);history(id,from,to,UUID.fromString(jsons.string(in,"currentUserId")));var value=full(id);outbox.enqueue(EventTopics.WORK_ORDER,to.equals("COMPLETED")?"WorkOrderCompleted":"WorkOrderStatusChanged",id,Map.of("workOrderId",id,"repairRequestId",value.get("repairRequestId"),"clientId",value.get("clientId"),"employeeId",value.get("employeeId"),"previousStatus",from,"currentStatus",to,"totalAmount",value.get("totalAmount")));jsons.reply(obs,value);}catch(Throwable e){jsons.fail(obs,e);}}
 @Override public void getSummary(JsonMessage req,StreamObserver<JsonMessage> obs){try{var value=full(UUID.fromString(jsons.string(jsons.read(req),"id")));jsons.reply(obs,Map.of("id",value.get("id"),"clientId",value.get("clientId"),"status",value.get("status"),"totalAmount",value.get("totalAmount"),"payable",Set.of("READY","COMPLETED").contains(value.get("status").toString())));}catch(Throwable e){jsons.fail(obs,e);}}
 private Map<String,Object> full(UUID id){var rows=jdbc.queryForList("select id,repair_request_id AS \"repairRequestId\",client_id AS \"clientId\",employee_id AS \"employeeId\",diagnosis,status,total_amount AS \"totalAmount\",created_at AS \"createdAt\",updated_at AS \"updatedAt\" from work_orders where id=?",id);if(rows.isEmpty())throw Status.NOT_FOUND.withDescription("Work order not found").asRuntimeException();var value=new LinkedHashMap<String,Object>(rows.get(0));value.put("services",jdbc.queryForList("select service_id AS \"serviceId\",service_name name,unit_price AS price,quantity,line_total AS \"lineTotal\" from work_order_services where work_order_id=?",id));value.put("parts",jdbc.queryForList("select part_id AS \"partId\",part_name name,unit_price AS price,quantity,line_total AS \"lineTotal\" from work_order_parts where work_order_id=?",id));return value;}
 private void ensureEditable(UUID id){String status=full(id).get("status").toString();if(!Set.of("DIAGNOSED","IN_PROGRESS").contains(status))throw new IllegalArgumentException("Work order cannot be edited in status "+status);}private void requireStaff(Map<String,Object>in){if(!Set.of("EMPLOYEE","ADMIN").contains(jsons.string(in,"role")))throw new SecurityException("Employee role is required");}private void authorize(Map<String,Object>v,Map<String,Object>in){if("CLIENT".equals(Objects.toString(in.get("role")))&&!v.get("clientId").toString().equals(Objects.toString(in.get("currentUserId"))))throw new SecurityException("Client can access only own work orders");}
 private void history(UUID id,String from,String to,UUID by){jdbc.update("insert into work_order_status_history(id,work_order_id,previous_status,new_status,changed_by,changed_at) values(?,?,?,?,?,?)",UUID.randomUUID(),id,from,to,by,java.time.OffsetDateTime.now(java.time.ZoneOffset.UTC));}private Map<String,Object> rpcRead(JsonMessage m){return jsons.read(m.getJson());}private List<Map<String,Object>> rpcList(JsonMessage m){Object v;try{v=new com.fasterxml.jackson.databind.ObjectMapper().findAndRegisterModules().readValue(m.getJson(),List.class);}catch(Exception e){throw new IllegalStateException(e);}@SuppressWarnings("unchecked")var result=(List<Map<String,Object>>)v;return result;}
}



